import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易要义卷二 * 下","description":"周易要义 - 周易要义卷二 * 下","frontmatter":{"title":"周易要义卷二 * 下","description":"周易要义 - 周易要义卷二 * 下"},"headers":[],"relativePath":"zh/classics/yaoyi/006.md","filePath":"zh/classics/yaoyi/006.md"}'),r={name:"zh/classics/yaoyi/006.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要义卷二-下" tabindex="-1">周易要义卷二 * 下 <a class="header-anchor" href="#周易要义卷二-下" aria-label="Permalink to “周易要义卷二 * 下”">​</a></h1><p>钦定四库全书</p><p>宋魏了翁辑豫至观</p><p>䷏</p><p>坤下震上 豫：利建侯行师。正义曰：谓之「豫」者，取逸豫之义，以和顺而动，动不违众，众皆说豫，故谓之豫也。动而众说，故可「利建侯」也。以顺而动，不加无罪，故可以「行师」也。无四德者，以逸豫之事不可以常行。豫，余虑反，悦豫也，备豫也。马云：豫，乐。震宫一世卦，</p><p>豫之时义大矣哉者，叹美为豫之善，言于逸豫之时，其义大矣。此叹卦也。凡言不尽意者，不可烦文具说，故叹之以示情，使后生思其余蕴，得意而忘言也。然叹卦有三体：一直叹时，如「大过之时大矣哉」之例是也；二叹时并用，如「险之时用大矣哉」之例是也。三叹时并义，「豫之时义大矣哉」之例是也。夫立卦之体，各象其时，时有屯夷，事非一揆，故爻来适时，有凶有吉。人之生世，亦复如斯，或逢治世，或遇乱时，出处存身，此道岂小？故曰「大矣哉」也。然时运虽多，大体不出四种者：一者治时，颐养之世是也。二者乱时，大过之世是也；三者离散之时，解缓之世是也。四者改易之时，革变之世是也。故举此四卦之时为叹，余皆可知。言用者，谓适时之用也。虽知居时之难，此事不小，而未知以何而用之耳。故坎、睽、蹇之时，宜用「君子，小人勿用」。用险取济，不可为常，斟酌得宜，是用时之大略。举险难等三卦，余从可知矣。又言「义」者，姤卦注云：「凡言义者，不尽于所见，中有意谓」者也。是其时皆有义也。略明佚乐之世，相随相遇之日、隐遁羁旅之时，凡五卦，其义不小，则余卦亦可知也。今所叹者十二卦，足以发明大义，恢弘妙理者也。凡于彖之末叹云「大哉」者，凡一十二卦，若豫、旅、遁、姤凡四卦，皆云「时义」。案：姤卦注云：「凡言义者，不尽于所见，中有意谓。」以此言之，则四卦，卦各未尽其理，其中更有余意，不可尽申，故总云「义」也。随之一卦亦言义，但与四卦其文稍别。四卦皆云时义，随卦则随时之义者，非但其中别有义意，又取随逐其时，故变云「随时之义」。大矣哉。睽、蹇、坎，此三卦皆云「时用」。案：睽卦注云：「睽离之时，非小人之所能用。」蹇卦亦云：「非小人之所能用。」此二卦言「大矣哉」者，则是大人能用，故云「大矣哉」。其中更无余义，唯大人能用，故云「用」不云「义」也。坎卦「时用」，则与睽、蹇稍别，注云「非用之常，用有时也」，谓坎险之事，时之须用，利益乃大，与睽、蹇「时」、「用」文同而义异也。解之「时」、革之「时」、颐之「时」，大过之「时」，此四卦直云「时」，不云「义」与「用」也。案解卦注难解之时，非治难时，故不言「用」；体尽于解之名，无有幽隐，故不曰「义」。以此注言之，直云「时」者，寻卦之名，则其意具尽，中间更无余义。</p><p>象曰：「雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。」正义曰：案诸卦之象，或云「云上于天」，或云「风行天上」，以类言之。今此应云「雷出地上」，乃云「雷出地奋，豫」者，雷是阳气之声，奋是震动之状，雷既出地震动万物，被阳气而生，各皆逸豫，故云「雷出地奋，豫」也。「先王以作乐崇德」者，雷是鼓动，故先王法此鼓动而作乐，崇盛德业，乐以发扬盛德故也。「殷荐之上帝」者，用此殷盛之乐，荐祭上帝也，象雷出地而向天也。「以配祖考」者，谓以祖考配上帝，用祖用考，若周夏正郊天，配灵威仰，以祖后稷配也。配祀明堂五方之帝，以考文王也，故云「以配祖考」也。奋，方问反。殷，于勤反，马云：「盛也。」说文云：「作乐之盛称殷。」</p><p>六二，介于石，不终日，贞吉。处豫之时，得位履中，安夫贞正，不苟求「豫」者也。顺不苟从，豫不违中，是以上交不谄，下交不渎。明祸福之所生，故不苟说；辨必然之理，故不改其操。介如「石」焉，「不终日」明矣。介，音界，纤介。古文作「砎」，郑故八反，云：谓磨砎也。马作「扴」，云：触小石声。荀说，音悦。正义：象曰「不终日，贞吉」，以中正者释「贞吉」之义。所以见其恶事，即能离去，不待终日守正吉者，以此六二居中守正，顺不苟从，豫不违中，故不须待其一日，终守「贞吉」也。</p><p>六三，盱豫，悔，迟有悔。居下体之极，处两卦之际，履非其位，承「动豫」之主，若其睢盱而豫，悔亦生焉。迟而不从，豫之所疾，位非所据，而以从豫，进退离悔，宜其然矣。盱，香于反，睢盱也。向云：「睢盱，小人喜悦之貌。」王肃云：「盱，大也。」郑云：「夸也。」说文云：「张目也。」字林火孤反，又火于反。子夏作「纡」。京作「污」。姚作「旴」，云：「日始出。」引诗「旴日始旦」。睢，香维反。说文云：「仰日也。」字林火佳反。</p><p>九四，由豫，大有得。勿疑，朋盍簪。处豫之时，居动之始，独体阳爻，众阴所从，莫不由之，以得其「豫」，故曰「由豫，大有得」也。夫不信于物，物亦疑焉，故「勿疑」，则朋合疾也。盍，合也；簪，疾也。由豫，由，从也。郑云：用也。马作「犹」，云：「犹豫，疑也。」盍，胡猎反，合也。簪，徐侧林反。子夏传同，疾也。郑云：「速也。」埤苍同，王肃又祖感反。古文作「贷」，京作「梣」，马作「臧」，荀作「宗」，虞作「戠」。戠，丛合也。蜀才本依京义从郑。若能不疑于物，以信待之，则众阴群朋合聚而疾来也。正义。象曰「由豫，大有得，志大行」者，释「由豫，大有得」之意。众阴既由之而豫，大有所得，是志意大行也。</p><p>䷐</p><p>震下兑上 随：元、亨、利、贞，无咎。正义曰：「元亨」者，于相随之世，必大得亨通。若其不大亨通，则元以相随，逆于时也。「利贞」者，相随之体，须利在得正。随而不正，则邪僻之道，必须「利贞」也。「无咎」者，有此四德乃无咎。以苟相从，涉于朋党，故必须四德乃「无咎」也。凡卦有四德者，或其卦当时之义即有四德，如乾、坤、屯、临、无妄，此五卦之时，即能四德备具。其随卦以恶相随，则不可也。有此四德乃无咎，无此四德则有咎也。与前五卦其义稍别。随，从也。震宫归魂卦。</p><p>六二，系小子，失丈夫。阴之为物，以处随世，不能独立，必有系也。居随之时，体分柔弱，而以乘夫刚动，岂能秉志？违于所近，随此失彼，弗能兼与。五处己上，初处己下，故曰「系小子，失丈夫」也。正义曰：「小子」谓初九也，「丈夫」谓九五也。初九处卑，故称「小子」。五居尊位，故称「丈夫」。六二既是阴柔，不能独立，所处必近系属初九，故云「系小子」。既属初九，则不得往应于五，故云「失丈夫」也。象曰「系小子，弗兼与」者，释「系小子」之意。既随此初九，则失彼九五丈夫，是不能两处兼有</p><p>六三，系丈夫，失小子。随有求得，利居贞。阴之为物，以处随世，不能独立，必有系也。虽体下卦，二已据初，将何所附？故舍初系四，志在「丈夫」。四俱无应，亦欲于己随之，则得其所求矣，故曰「随有求得」也。应非其正，以系于人，何可以妄？故「利居贞」也。初处己下，四处己上，故曰「系丈夫，失小子」也。象曰：「系丈夫」，志舍下也。下谓初也。</p><p>䷑</p><p>巽下艮上 蛊：元亨，利涉大川。先甲三日，后甲三日。正义曰：「蛊者，事也。有事营为，则大得亨通。有为之时，利在拯难，故利涉大川也。先甲三日，后甲三日者，甲者创制之令，既在有为之时，不可因仍旧令。今用创制之令，以治于人，人若犯者，未可即加刑罚。以民未习，故先此宣令之前三日，殷勤而语之。又于此宣令之后三日，更丁宁而语之。其人不从，乃加刑罚也。」其褚氏、何氏、周氏等并同郑义，以为甲者，造作新令之日。甲前三日，取改过自新，故用辛也。甲后三日，取丁宁之义，故用丁也。今案：辅嗣注「甲曰创制之令」，不云创制之日。又巽卦九五：「先庚三日，后庚三日。」辅嗣注：「申命令为之庚。」辅嗣又云：「甲、庚皆申命之谓。」则辅嗣不以甲为创制之日。而诸儒不顾辅嗣注旨，妄作异端，非也。蛊，音古，事也，惑也，乱也。左传云：「于文，皿虫为蛊。」又云：「女惑男，风落山，谓之蛊。」徐又姬祖反，一音故，巽宫归魂卦。先，息荐反，彖并注同。后，胡豆反。</p><p>彖曰：「蛊，刚至，天行也。」正义曰：「刚上而柔下，巽而止，蛊」者，此释蛊卦之名，并明称「蛊」之义也。以上刚能断制，下柔能施令，巽顺止静，故可以有为也。褚氏云：「蛊者，惑也。物既惑乱，终致损坏，当须有事也，有为治理也。故序卦云：蛊者，事也。」谓物蛊必有事，非谓训蛊为事，义当然也。「蛊，元亨，而天下治」者，释「元亨」之义。以有为而得「元亨」，是天下治理也。「利涉大川，往有事也」者，释「利涉大川」也。蛊者，有为之时，拔拯危难，往当有事，故「利涉大川」。此则假外象以喻危难也。「先甲三日，后甲三日，终则有始，天行」者，释「先甲三日，后甲三日」之义也。民之犯令，告之已终，更复从始，告之殷勤不已，若天之行。四时既终，更复从春为始，象天之行，故云「天行也」。释注「蛊者」至「四时也」。正义曰：「蛊者，有事待能之时」者，物既蛊坏，须有事营为，所作之事，非贤能不可，故经云：「干父之蛊，干则能也。</p><p>甲者，创制之令」者，甲为十日之首，创造之令为在后诸令之首，故以创造之令谓之为甲。故汉时谓令之重者谓之「甲令」，则此义也。</p><p>创制不可责之以旧者，以人有犯令而致罪者，不可责之旧法，有犯则刑，故须先后三日，殷勤语之，使晓知新令，而后乃诛。诛谓兼通责让之罪，非专谓诛杀也。说，音悦。创，初亮反。此俗字也，依字作创。</p><p>象曰：「山下」至「育德」。正义曰：必云「山下有风」者，风能摇动，散布润泽。今「山下有风」，取君子能以恩泽下振于民，育养已德振民象山下有风育德象山在上也振旧之慎，反，济也。师读音真。振振，仁厚也。「育」，王肃作「毓」，古「育」字。</p><p>初六，干父之蛊，有子，考无咎。厉，终吉。处事之首，始见任者也。以柔巽之质，干父之事，能承先轨，堪其任者也，故曰「有子」也。任为事首，能堪其事，「考」乃「无咎」也，故曰「有子，考无咎」也。当事之首，是以危也。能堪其事，故「终吉」也。「有子，考无咎」绝句。周依马、王肃以「考」绝句。正义：「象曰干父之蛊，意承考」者，释「干父之蛊」义。凡堪干父事，不可小大损益，一依父命，当量事制宜，以意承「考」而已。对文父没称「考」，若散而言之，生亦称「考」。若康诰云「大伤厥考心」，是父在称「考」。此避干父之文，故变云「考」也。</p><p>初六，干父之蛊，有子，考无咎。厉，终吉。处事之首，始见任者也。以柔巽之质，干父之事，能承先轨，堪其任者也，故曰「有子」也。任为事首，能堪其事，「考」乃「无咎」也，故曰「有子，考无咎」也。当事之首，是以危也。能堪其事，故「终吉」也。「有子，考无咎」绝句。周依马、王肃以「考」绝句。正义：「象曰干父之蛊，意承考」者，释「干父之蛊」义。凡堪干父事，不可小大损益，一依父命，当量事制宜，以意承「考」而已。对文父没称「考」，若散而言之，生亦称「考」。若康诰云「大伤厥考心」，是父在称「考」。此避干父之文，故变云「考」也。</p><p>䷒</p><p>兑下坤上。 临：元亨，利，贞。至于八月有凶。正义曰：案序卦云：「临，大也。」以阳之浸长，其德壮大，可以监临于下，故曰「临」也。刚既浸长，说而且顺，又以刚居中，有应于外，大得亨通而利正也，故曰「元亨，利贞」也。「至于八月有凶」者，以物盛必衰，阴长阳退，临为建丑之月，从建丑至于八月建申之时，三阴既盛，三阳方退，小人道长，君子道消，故八月有凶也。以盛不可终保，圣人作易以戒之也。临，如字，序卦云：「大也。」坤宫二世卦</p><p>彖曰：临，刚至不久也。正义曰：「临，刚浸而长，说而顺」者，此释临义也。据诸卦之例，「说而顺」之下，应以临字结之。此无「临」字者，以其刚中而应，亦是临义，故不得于刚中之上而加「临」也。刚中而应，大亨以正，天之道者，天道以刚居中，而下与地相应，使物大得亨通而利正，故乾卦「元亨利贞」。今此临卦其义亦然，故云「天之道也」。</p><p>八月者，何氏云：从建子阳生，至建未为八月。褚氏云：自建寅至建酉为八月。今案：此注云：小人道长，君子道消，宜据否卦之时，故以临卦建丑而至否卦建申为八月也。</p><p>䷓</p><p>坤下巽上 观，盥而不荐，有孚颙若。王道之可观者，莫盛乎宗庙。宗庙之可观者，莫盛于盥也。至荐简略，不足复观，故观盥而不观荐也。孔子曰：「禘自既灌而往者，吾不欲观之矣。」尽夫观盛，则「下观而化」矣。故观至盥则「有孚颙若」也。观，官唤反，示也。乾宫四世卦。盥音管。</p><p>圣人以神道设教，而天下服矣。统说：观之为道，不以刑制使物，而以观感化物者也。神则无形者也。不见天之使四时，而四时不忒；不见圣人使百姓，而百姓自服也。</p><p>初六，童观，小人无咎，君子吝。处于观时，而最远朝美，体于阴柔，不能自进，无所鉴见，故曰童观。趣顺而已，无所能为，小人之道也，故曰「小人无咎」。君子处大观之时，而为童观，不亦鄙乎！童观，马云：「童犹独也。」郑云：「稚也。」远，袁万反。朝，直遥反。</p><p>「童观、𬮭观」，皆读为去声也。观国如字；或音官唤反。尽夫观盛，故观至大观在上，王肃音官。以观天下，徐唯此一字作官音。观。盥而不荐，观之为道，而以观感。风行地上，观。处于观时。君子处大观之时，大观广鉴亦音官。居观之时，为观之主，观之盛也。从「尽夫观」以下，并官唤反，余不出者，并音官。</p><p>九五：观我生，君子无咎。居于尊位，为观之主，宣弘大化，光于四表，观之极者也。上之化下，犹风之靡草，故观民之俗，以察己道。百姓有罪，在予一人。君子风著，己乃无咎。上为化主，将欲自观，乃观民也。象曰：「观我生」，观民也。正义曰：九五居尊，为观之主。四海之内，由我而化。我教化善，则天下有君子之风；教化不善，则天下著小人之俗。故观民以察我道，有君子之风著，则无咎也。周易要义卷二下</p>',32)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
